// Laya reorderer on onnxruntime-react-native. OFF by default (policy.laya.enabled = false).
// Gate to switch it on: docs/phase3-architecture.md §1.4. What is ready now: the native runtime,
// the session, tensor plumbing and the decision rule (reorder only, no "ninguna" cut). What is not
// ported yet: Laya's BPE tokenizer and `build_sequence` (encodeLaya below). Their spec is
// src/core/knowledge/laya/__fixtures__/laya_io.json, generated by experiments/laya/laya_fixtures.py.
import type { InferenceSession } from 'onnxruntime-react-native';

import type { Reranker } from '@/core/knowledge/rerank';

import { findSideLoaded } from './embedder';
import { ort } from './ort';

export interface LayaEncoded {
  seq: number[]; // token ids of the whole question row
  markers: number[]; // positions of the option markers, options in criteria order
  qtype: number; // 0 for a choice question in laya 0.5.1 (QTYPES)
}

/** Port target. Throws until the tokenizer + build_sequence port passes laya_io.json. */
export function encodeLaya(_state: string, _criteria: string[]): LayaEncoded {
  throw new Error('Laya encoder not ported yet: see src/llm/laya.ts header');
}

export async function openLayaSession(onnxName: string): Promise<InferenceSession> {
  const file = findSideLoaded(onnxName);
  if (!file) throw new Error(`Laya model ${onnxName} not found; run scripts/push-knowledge.sh --with-laya`);
  return ort().InferenceSession.create(file.uri.replace(/^file:\/\//, ''), {
    intraOpNumThreads: 2,
    graphOptimizationLevel: 'all',
  });
}

/** One question row through the session; returns the option logits (markers order). */
export async function runLaya(session: InferenceSession, enc: LayaEncoded, padId = 0): Promise<number[]> {
  const { Tensor } = ort();
  const L = enc.seq.length;
  const k = Math.max(enc.markers.length, 2); // the exported head needs >= 2 marker columns
  const ids = new BigInt64Array(L);
  const att = new BigInt64Array(L);
  for (let i = 0; i < L; i++) {
    ids[i] = BigInt(enc.seq[i] ?? padId);
    att[i] = 1n;
  }
  const mpos = new BigInt64Array(k);
  const mmask = new Uint8Array(k);
  enc.markers.forEach((p, i) => {
    mpos[i] = BigInt(p);
    mmask[i] = 1;
  });
  const out = await session.run({
    input_ids: new Tensor('int64', ids, [1, L]),
    attention_mask: new Tensor('int64', att, [1, L]),
    marker_pos: new Tensor('int64', mpos, [1, k]),
    marker_mask: new Tensor('bool', mmask, [1, k]),
    qtype: new Tensor('int64', BigInt64Array.from([BigInt(enc.qtype)]), [1]),
  });
  return Array.from(out.logits.data as Float32Array).slice(0, enc.markers.length);
}

/** Reorder-only reranker: sorts the pool by Laya's option logits, ignoring "ninguna". */
export function layaReranker(session: InferenceSession, labelOf: (id: string) => string): Reranker {
  return {
    id: 'laya-rlcd6-gather-int8',
    async rerank(query, pool) {
      const criteria = [...pool.map(labelOf), 'ninguna de estas opciones'];
      const logits = await runLaya(session, encodeLaya(query, criteria));
      const opts = pool.map((id, i) => ({ id, s: logits[i] ?? -Infinity }));
      return opts.sort((a, b) => b.s - a.s).map((o) => o.id);
    },
  };
}
